3	import { useVisit, type Visit, restBaseUrl } from '@openmrs/esm-framework';
4	import { usePatientChartStore } from '../store/patient-chart-store';
5	
6	export interface VisitMutationOptions {
7	  encounters?: boolean;
8	  notes?: boolean;
9	  orders?: boolean;
10	  observations?: boolean;
11	}
12	
13	/**
14	 * Hook providing optimistic update utilities for visit-related data.
15	 * This hook helps reduce the number of network requests by updating SWR caches directly
16	 * instead of triggering full revalidations across all visit-related hooks.
17	 *
18	 * @param patientUuid The UUID of the patient
19	 * @returns Object containing optimistic update functions
20	 */
21	export function useOptimisticVisitMutations(patientUuid: string) {
22	  const { mutate } = useSWRConfig();
23	  const { visitContext, mutateVisitContext } = usePatientChartStore(patientUuid);
24	
25	  /**
26	   * Optimistically updates visit data in SWR caches without triggering network requests.
27	   * Updates both the current visit cache and visit list caches.
28	   */
29	  const updateVisitOptimistically = useCallback(
30	    (visitUuid: string, updates: Partial<Visit>) => {
31	      // Update current visit SWR cache if it matches
32	      if (visitContext?.uuid === visitUuid) {
33	        mutateVisitContext?.();
34	      }
35	
36	      // Update visit lists across all hooks using regex pattern matching
37	      const visitListPattern = new RegExp(`${restBaseUrl}/visit\\?patient=${patientUuid}`);
38	
39	      mutate(
40	        visitListPattern,
41	        (current: any) => {
42	          if (!current?.data?.results) return current;
43	          return {
44	            ...current,
45	            data: {
46	              ...current.data,
47	              results: current.data.results.map((visit: Visit) =>
48	                visit.uuid === visitUuid ? { ...visit, ...updates } : visit,
49	              ),
50	            },
51	          };
52	        },
53	        false, // Don't revalidate
54	      );
55	    },
56	    [visitContext, mutateVisitContext, mutate, patientUuid],
57	  );
58	
59	  /**
60	   * Optimistically removes a visit from SWR caches without triggering network requests.
61	   * Removes from visit lists and revalidates current visit if the deleted visit was current.
62	   */
63	  const removeVisitOptimistically = useCallback(
64	    (visitUuid: string) => {
65	      // Remove from all visit list caches
66	      const visitListPattern = new RegExp(`${restBaseUrl}/visit\\?patient=${patientUuid}`);
67	
68	      mutate(
69	        visitListPattern,
70	        (current: any) => {
71	          if (!current?.data?.results) return current;
72	          return {
73	            ...current,
74	            data: {
75	              ...current.data,
76	              results: current.data.results.filter((visit: Visit) => visit.uuid !== visitUuid),
77	            },
78	          };
79	        },
80	        false, // Don't revalidate
81	      );
82	
83	      // If deleted visit was current, revalidate current visit to get new state
84	      if (visitContext?.uuid === visitUuid) {
85	        mutateVisitContext?.();
86	      }
87	    },
88	    [visitContext, mutateVisitContext, mutate, patientUuid],
89	  );
90	
91	  /**
92	   * Optimistically adds a new visit to SWR caches without triggering network requests.
93	   * Adds to visit lists and updates current visit cache if appropriate.
94	   */
95	  const addVisitOptimistically = useCallback(
96	    (newVisit: Visit) => {
97	      // Add to visit list caches
98	      const visitListPattern = new RegExp(`${restBaseUrl}/visit\\?patient=${patientUuid}`);
99	
100	      mutate(
101	        visitListPattern,
102	        (current: any) => {
103	          if (!current?.data?.results) return current;
104	          return {
105	            ...current,
106	            data: {
107	              ...current.data,
108	              results: [newVisit, ...current.data.results],
109	            },
110	          };
111	        },
112	        false, // Don't revalidate
113	      );
114	
115	      // If this is an active visit (no stopDatetime), update current visit cache
116	      if (!newVisit.stopDatetime) {
117	        mutate(
118	          `${restBaseUrl}/visit?patient=${patientUuid}&v=custom`,
119	          (current: any) => ({
120	            ...current,
121	            data: newVisit,
122	          }),
123	          false, // Don't revalidate
124	        );
125	      }
126	    },
127	    [mutate, patientUuid],
128	  );
129	
130	  /**
131	   * Selectively invalidates only specific visit-related data that cannot be optimistically updated.
132	   * This replaces the global mutateVisit() pattern with targeted revalidation.
133	   */
134	  const invalidateVisitRelatedData = useCallback(
135	    (options: VisitMutationOptions = {}) => {
136	      const promises = [];
137	
138	      if (options.encounters) {
139	        promises.push(mutate(new RegExp(`${restBaseUrl}/encounter\\?patient=${patientUuid}`)));
140	      }
141	      if (options.notes) {
142	        promises.push(mutate(new RegExp(`${restBaseUrl}/encounter\\?patient=${patientUuid}.*obs=`)));
143	      }
144	      if (options.orders) {
145	        promises.push(mutate(new RegExp(`${restBaseUrl}/order\\?patient=${patientUuid}`)));
146	      }
147	      if (options.observations) {
148	        promises.push(mutate(new RegExp(`${restBaseUrl}/obs\\?patient=${patientUuid}`)));
149	      }
150	
151	      return Promise.all(promises);
